package com.shopsphere.service; import com.shopsphere.entity.*; import com.shopsphere.repository.*; import com.shopsphere.security.CurrentUser; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.util.*; @Service public class WishlistService {private final WishlistItemRepository repo;private final ProductRepository products;private final CurrentUser current;public WishlistService(WishlistItemRepository r,ProductRepository p,CurrentUser c){repo=r;products=p;current=c;} public List<UUID> all(Authentication a){return repo.findAllByUser(current.get(a)).stream().map(x->x.getProduct().getId()).toList();} public void add(UUID pid,Authentication a){User u=current.get(a);Product p=products.findById(pid).orElseThrow();if(repo.findByUserAndProduct(u,p).isEmpty()){WishlistItem x=new WishlistItem();x.setUser(u);x.setProduct(p);repo.save(x);}} public void remove(UUID pid,Authentication a){User u=current.get(a);products.findById(pid).ifPresent(p->repo.findByUserAndProduct(u,p).ifPresent(repo::delete));}}
